def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    me = [a for a, b in history]
    opp = [b for a, b in history]
    opp_d = sum(1 for x in opp if x == 'D')

    if n == 98 and opp_d == 0:
        return 'D'

    last_m, last_o = history[-1]
    recent_d10 = sum(1 for x in opp[-10:] if x == 'D')
    recent_d20 = sum(1 for x in opp[-20:] if x == 'D')

    punish_count = 0
    safe_count = 0
    for i in range(1, n):
        if me[i - 1] == 'D' and opp[i] == 'D':
            punish_count += 1
        if i >= 2:
            if (me[i - 2] == 'D' and opp[i - 1] == 'C' and
                    me[i - 1] == 'C' and opp[i] == 'C'):
                safe_count += 1

    run_opp_d = 0
    for x in reversed(opp):
        if x == 'D':
            run_opp_d += 1
        else:
            break

    dd_run = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            dd_run += 1
        else:
            break

    mostly_cooperative = opp_d <= max(1, n // 4)
    cooperative_enough = opp_d <= max(2, n // 3) and recent_d20 <= 3
    hard_defector = opp_d * 2 > n or recent_d10 >= 5 or run_opp_d >= 3
    exploitable = (safe_count >= 1 and punish_count == 0 and
                   mostly_cooperative and recent_d10 <= 2)

    if last_o == 'D':
        if run_opp_d == 1 and me[-2] == 'D' and opp[-2] == 'C':
            return 'C' if (cooperative_enough or exploitable) else 'D'

        if last_m == 'D':
            if hard_defector:
                return 'D'
            if dd_run <= 2 and (mostly_cooperative or exploitable):
                return 'C'
            return 'D'

        if hard_defector:
            return 'D'
        if (run_opp_d == 1 and mostly_cooperative and safe_count >= 1 and
                punish_count == 0 and recent_d20 <= 1):
            return 'C'
        return 'D'

    if last_m == 'D':
        return 'D' if exploitable else 'C'

    return 'D' if exploitable else 'C'
